package io.chronos.api;
import io.micrometer.core.instrument.MeterRegistry; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.util.concurrent.atomic.AtomicLong; import java.util.concurrent.atomic.AtomicReference;
@Component public class ChronosMetrics {
 private final JdbcTemplate jdbc; private final AtomicLong queue=new AtomicLong(),running=new AtomicLong(),workers=new AtomicLong(); private final AtomicReference<Double> p95=new AtomicReference<>(0d);
 public ChronosMetrics(JdbcTemplate jdbc,MeterRegistry registry){this.jdbc=jdbc;registry.gauge("chronos_queue_depth",queue);registry.gauge("chronos_running_count",running);registry.gauge("chronos_worker_count",workers);registry.gauge("chronos_run_duration_p95_seconds",p95,AtomicReference::get);for(String s:new String[]{"QUEUED","RUNNING","SUCCEEDED","FAILED","DEAD","CANCELLED","SKIPPED"}){AtomicLong count=new AtomicLong();registry.gauge("chronos_runs",io.micrometer.core.instrument.Tags.of("status",s),count);counts.put(s,count);}}
 private final java.util.Map<String,AtomicLong> counts=new java.util.concurrent.ConcurrentHashMap<>();
 @Scheduled(fixedDelay=5000) public void refresh(){queue.set(value("select count(*) from job_run where status='QUEUED'"));running.set(value("select count(*) from job_run where status='RUNNING'"));workers.set(value("select count(*) from worker_node where heartbeat_at>now()-interval '30 seconds'"));counts.forEach((s,c)->c.set(jdbc.queryForObject("select count(*) from job_run where status=?",Long.class,s)));Double d=jdbc.queryForObject("select coalesce(percentile_cont(0.95) within group(order by extract(epoch from (finished_at-started_at))),0) from job_run where finished_at>now()-interval '1 day' and started_at is not null",Double.class);p95.set(d==null?0:d);}
 private long value(String sql){Long n=jdbc.queryForObject(sql,Long.class);return n==null?0:n;}
}
